import { useEffect, useState } from 'react'
export default function Cozinha(){const [pedidos,setPedidos]=useState([]),[erro,setErro]=useState('');const carregar=()=>fetch('/api/cozinha').then(r=>r.json()).then(setPedidos).catch(e=>setErro(e.message));useEffect(()=>{carregar();const t=setInterval(carregar,10000);return()=>clearInterval(t)},[]);const iniciar=async id=>{const r=await fetch(`/api/cozinha/${id}/iniciar`,{method:'PATCH'});if(!r.ok){const d=await r.json().catch(()=>({}));alert(d.erro||'Não foi possível iniciar.');return}carregar()};return <div><div className="section-head"><div><h2>KDS / Cozinha</h2><div className="muted">Pedidos recebidos e em produção, atualizados automaticamente</div></div></div>{erro&&<div style={{color:'#d32f2f'}}>{erro}</div>}<div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(300px,1fr))',gap:14}}>{pedidos.map(p=><div className="card" key={p.id}><div style={{display:'flex',justifyContent:'space-between'}}><strong>#{p.numero}</strong><span className="pill">{p.status}</span></div><div className="muted" style={{margin:'8px 0'}}>{p.cliente?.nome}</div>{p.itens.map(i=><div key={i.id} style={{margin:'6px 0'}}><strong>{i.quantidade}x</strong> {i.nome}{i.adicionais?.length>0&&<div className="muted" style={{paddingLeft:20}}>{i.adicionais.map(a=>a.nome).join(', ')}</div>}</div>)}{p.status==='RECEBIDO'&&<button className="btn btn-primary" style={{width:'100%',marginTop:12}} onClick={()=>iniciar(p.id)}>Iniciar produção</button>}</div>)}</div>{!pedidos.length&&<div className="card empty-state">Nenhum pedido na cozinha.</div>}</div>}
